        vouchers: [
            { id: 'v1', label: 'Flash Sale Sparepart', disc: 'Rp25.000', min: 'Min. belanja Rp150.000', bg: 'bg-red-50 dark:bg-red-900/10 border-red-100 dark:border-red-900/20' },
            { id: 'v2', label: 'Diskon Member Baru', disc: '10%', min: 'Min. belanja Rp100.000', bg: 'bg-blue-50 dark:bg-blue-900/10 border-blue-100 dark:border-blue-900/20' },
            { id: 'v3', label: 'Gratis Ongkir', disc: 'Rp0', min: 'Min. belanja Rp200.000', bg: 'bg-green-50 dark:bg-green-900/10 border-green-100 dark:border-green-900/20' }
        ],
        claimed: {}
